// triggered by InventoryReserved (at-least-once). Charges, then emits next event.
async function onInventoryReserved(evt) {
  const charge = await payments.charge(evt.orderId, evt.amount); // side effect
  await db.insert('charges', { orderId: evt.orderId, chargeId: charge.id });
  await broker.publish('PaymentCharged', { orderId: evt.orderId });
  ack(evt);
}
